{
  "dependencies": {
    "@opencode/plugin": "2.0.22"
  },
  "type": "module"
}

#!/usr/bin/env node
import chalk from 'chalk'
import { createRequire } from 'node:module'
import { runJoin } from './commands/join.js'
import { runUpdate } from './commands/update.js'
import { runSingleCommand } from './commands/single.js'
import { runWizard } from './commands/wizard.js'
import { exit } from './utils/process.js'
import { runMigrateCommand } from './commands/migrate.js'
import { findLegacyInstall } from './utils/legacy-check.js'

function printHelp(version) {
  console.log(`agent-harness v${version}`)
  console.log()
  console.log('Usage:')
  console.log('  npx @plainconceptsplatform/agent-harness             Install the harness (full wizard)')
  console.log('  npx @plainconceptsplatform/agent-harness <command>   Run a single step command')
  console.log()
  console.log('Commands:')
  console.log('  update          Bring the harness up to date from saved config (no prompts)')
  console.log('  migrate         Move a v1 (opencode-onboard) project to v2, keeping your content')
  console.log('  join            Set up a teammate\'s machine (checks & local installs only)')
  console.log('  clean           Run AI files cleanup step')
  console.log('  platform        Run platform selection step')
  console.log('  copy            Run content copy step')
  console.log('  openspec        Run OpenSpec initialization step')
  console.log('  models          Run models selection step')
  console.log('  optimization    Run token optimization tools step')
  console.log('  browser         Run browse installer step')
  console.log('  metadata        Write onboarding metadata step')
  console.log()
  console.log('Options:')
  console.log('  -h, --help      Show this help message')
}

if (process.stdout.isTTY) console.clear()
console.log()
const require = createRequire(import.meta.url)
const { version } = require('../package.json')
const args = process.argv.slice(2)

if (args.includes('-h') || args.includes('--help')) {
  printHelp(version)
  exit()
}

async function refuseLegacyInstall() {
  const legacy = await findLegacyInstall()
  if (!legacy) return false

  console.log(chalk.red('This project was set up by opencode-onboard v1.'))
  console.log()
  if (legacy.files.length > 0) console.log(chalk.dim(`  config:  ${legacy.files.join(', ')}`))
  if (legacy.skills.length > 0) {
    const shown = legacy.skills.slice(0, 3).join(', ')
    const rest = legacy.skills.length > 3 ? `, +${legacy.skills.length - 3} more` : ''
    console.log(chalk.dim(`  skills:  ${shown}${rest}`))
  }
  console.log()
  console.log('agent-harness v2 renamed both the config files and the skill prefix,')
  console.log('and it does not migrate v1 projects. Continuing would leave the harness')
  console.log('half-patched without reporting an error.')
  console.log()
  console.log('Migrate it, keeping your generated skills and custom engineers:')
  console.log(chalk.dim('  npx @plainconceptsplatform/agent-harness migrate'))
  console.log(chalk.dim('  npx @plainconceptsplatform/agent-harness update'))
  console.log()
  console.log(chalk.dim('Add --dry-run to see what migrate would change first.'))
  return true
}

// Ctrl-C out of an @inquirer prompt throws ExitPromptError; that is a normal
// cancellation, not a crash, so it must not exit non-zero.
async function main() {
  // migrate is the way out of a v1 project, so it must run before the guard
  // that refuses v1 projects.
  if (args[0] === 'migrate') {
    await runMigrateCommand(args.slice(1))
    return
  }
  if (await refuseLegacyInstall()) {
    exit(1)
    return
  }
  if (args.length === 0) {
    await runWizard(version)
    return
  }
  if (args[0] === 'join') {
    await runJoin()
    return
  }
  if (args[0] === 'update') {
    await runUpdate()
    return
  }
  if (!await runSingleCommand(args[0])) {
    console.log(chalk.red(`Unknown command: ${args[0]}`))
    console.log()
    printHelp(version)
    exit(1)
  }
}

try {
  await main()
} catch (err) {
  if (err.name === 'ExitPromptError') {
    console.log()
    console.log(chalk.yellow('Cancelled.'))
  } else {
    console.error(chalk.red('\nUnexpected error:'), err.message)
    exit(1)
  }
}
exit()

import { execa } from 'execa'
import fse from 'fs-extra'
import { header, info, success, warn, error } from '../../utils/exec.js'
import os from 'os'
import path from 'path'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const BROWSER_PRESET_PATH = path.resolve(__dirname, '../../presets/browser.json')
const browserPreset = await fse.readJson(BROWSER_PRESET_PATH)

export async function installBrowser() {
  header('Step 9, Installing browse')

  try {
    const install = await execa(browserPreset.installer.command, browserPreset.installer.args, {
      cwd: os.homedir(),
      reject: false,
    })

    if (install.exitCode !== 0) {
      warn('browse npm install exited with non-zero code')
      if (install.stderr) info(install.stderr)
      return
    }
    success('browse installed')
  } catch (err) {
    error(`Failed to install browse: ${err.message}`)
    return
  }

  try {
    const setup = await execa(browserPreset.setup.command, browserPreset.setup.args, {
      cwd: os.homedir(),
      reject: false,
      timeout: 180000,
    })

    if (setup.exitCode === 0) {
      success('browse paired with your browser')
      if (setup.stdout) info(setup.stdout.trim())
    } else {
      // browse install opens the Chrome Web Store and waits for the extension to connect.
      // A non-zero exit often just means the user didn't finish pairing in time; browse is
      // still installed and usable once they add the extension and run `browse pair`.
      warn('browse setup did not complete — install the extension and run `browse pair`')
      if (setup.stderr) info(setup.stderr)
    }
  } catch (err) {
    error(`Failed to set up browse: ${err.message}`)
  }
}

import { checkbox } from '@inquirer/prompts'
import fse from 'fs-extra'
import path from 'path'
import { fileURLToPath } from 'url'
import { findAiFiles } from '../../utils/copy.js'
import { header, info, success, warn } from '../../utils/exec.js'
import { MARKERS } from '../../utils/terminal.js'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const CLEAN_PRESET_PATH = path.resolve(__dirname, '../../presets/clean.json')
const cleanPreset = await fse.readJson(CLEAN_PRESET_PATH)

async function childrenExcludingPreserved(dir) {
  const results = []
  if (!await fse.pathExists(dir)) return results
  const entries = await fse.readdir(dir)
  for (const entry of entries) {
    if (cleanPreset.preserveSubfolders.includes(entry)) continue
    results.push(path.join(dir, entry))
  }
  return results
}

async function isPopulated(filePath) {
  if (!await fse.pathExists(filePath)) return false
  const content = await fse.readFile(filePath, 'utf-8')
  const trimmed = content.trim()
  if (!trimmed) return false
  if (trimmed.startsWith('<!-- onboard-prompt')) return false
  return true
}

async function hasOpenspecHistory(cwd) {
  const changesDir = path.join(cwd, 'openspec', 'changes')
  const archiveDir = path.join(cwd, 'openspec', 'archive')
  if (await fse.pathExists(changesDir)) {
    const entries = await fse.readdir(changesDir)
    if (entries.length > 0) return true
  }
  if (await fse.pathExists(archiveDir)) {
    const entries = await fse.readdir(archiveDir)
    if (entries.length > 0) return true
  }
  return false
}

export async function cleanAiFiles({ removeLegacyConfig = false } = {}) {
  header('Step 2, Existing AI config files')

  const cwd = process.cwd()
  const ctx = {
    hasDesign: await isPopulated(path.join(cwd, 'DESIGN.md')),
    hasArchitecture: await isPopulated(path.join(cwd, 'ARCHITECTURE.md')),
    hasOpenspec: await hasOpenspecHistory(cwd),
  }

  if (ctx.hasDesign) info('DESIGN.md exists and is populated, keeping it')
  if (ctx.hasArchitecture) info('ARCHITECTURE.md exists and is populated, keeping it')
  if (ctx.hasOpenspec) info('openspec/ history exists, keeping it')

  const legacyConfig = path.join(cwd, '.opencode', 'opencode.json')
  if (removeLegacyConfig && await fse.pathExists(legacyConfig)) {
    await fse.remove(legacyConfig)
    info('Removed legacy .opencode/opencode.json')
  }

  const flatFiles = await findAiFiles(cwd, cleanPreset.detectFiles)
  const dirTargets = cleanPreset.directoryTargets
  const dirEntries = []
  for (const dirName of dirTargets) {
    const dirPath = path.join(cwd, dirName)
    const children = await childrenExcludingPreserved(dirPath)
    if (children.length > 0) {
      dirEntries.push(...children)
    } else if (await fse.pathExists(dirPath)) {
      // Directory exists but all children are preserved (e.g. only skills/):
      // still offer the directory itself as a removable option.
      dirEntries.push(dirPath)
    }
  }

  const filteredFlat = flatFiles.filter(f => {
    const rel = path.relative(cwd, f)
    if (dirTargets.includes(rel)) return false
    if (cleanPreset.preserve.some(p => rel === p || rel.startsWith(p + path.sep))) return false
    return true
  })

  const allToRemove = [...filteredFlat, ...dirEntries]

  if (allToRemove.length === 0) {
    success('No existing AI config files to remove')
    return ctx
  }

  const choices = allToRemove.map(f => ({
    name: path.relative(cwd, f).replace(/\\/g, '/'),
    value: f,
    checked: true,
  }))

  const selected = await checkbox({
    message: cleanPreset.selectionMessage,
    choices,
  })

  if (!selected || selected.length === 0) {
    success('No AI config files selected for removal')
    return ctx
  }

  warn('Removing selected AI config files:')
  for (const f of selected) {
    info(`${MARKERS.EMPTY}${f.replace(cwd + path.sep, '')}`)
    await fse.remove(f)
  }
  success('Removed existing AI config files')

  return ctx
}

import fse from "fs-extra"
import path from "path"
import { fileURLToPath } from "url"
import { copyContent, recordManagedContent } from "../../utils/copy.js"
import { error, header, success } from "../../utils/exec.js"
import { exit } from "../../utils/process.js"
import { patchAgentGuidance, patchAgentsMd } from "./agents.js"
import { patchArchiveCommand, patchOpsShip, patchOpsReview, patchOpsBacklog } from "./commands.js"
import { installSkills, removeRetiredFiles } from "./skills.js"
import { generateFullstackEngineer, removeLegacyStartupDirectives } from "./fullstack-engineer.js"
import { patchOpencodeJson, patchOpencodePackage } from "./opencode-json.js"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const CONTENT_DIR = path.resolve(__dirname, "../../../harness")

export async function copyContentStep(platform, ctx = {}) {
  header("Step 5, Copying agent-harness files")

  const dest = process.cwd()

  // Support both old single-string platform and new { backlogPlatform, repoPlatform }
  const backlogPlatform = typeof platform === 'object' ? platform.backlogPlatform : platform
  const repoPlatform = typeof platform === 'object' ? platform.repoPlatform : platform

  try {
    await copyContent(CONTENT_DIR, dest, platform, ctx)

    // .gitignore is stripped by npm during publish, so the source file is _gitignore.
    // Also, fse.copy with overwrite:false won't overwrite an existing .gitignore,
    // so merge manually to preserve both opencode's defaults and our additions.
    const srcGitignore = path.join(CONTENT_DIR, ".opencode", "_gitignore")
    const destGitignore = path.join(dest, ".opencode", ".gitignore")
    if (await fse.pathExists(srcGitignore)) {
      const srcLines = (await fse.readFile(srcGitignore, "utf-8")).split("\n").map(l => l.trim()).filter(Boolean)
      const destLines = (await fse.pathExists(destGitignore))
        ? (await fse.readFile(destGitignore, "utf-8")).split("\n").map(l => l.trim()).filter(Boolean)
        : []
      const merged = Array.from(new Set([...destLines, ...srcLines]))
      await fse.writeFile(destGitignore, `${merged.join("\n")}\n`, "utf-8")
    }

    // Remove the _gitignore template from dest: it was only needed for the merge above.
    const destGitignoreTemplate = path.join(dest, ".opencode", "_gitignore")
    if (await fse.pathExists(destGitignoreTemplate)) {
      await fse.remove(destGitignoreTemplate)
    }

    const rootsFile = path.join(dest, ".opencode", "source-roots.json")
    if (!ctx.updateMode || !await fse.pathExists(rootsFile)) {
      await fse.writeJson(
        rootsFile,
        {
          mode: ctx.sourceMode || "current",
          // An empty array is truthy, so `|| [dest]` never kicked in and reruns
          // wrote `roots: []`, leaving agents with no source scope.
          roots: ctx.sourceRoots?.length ? ctx.sourceRoots : [dest],
        },
        { spaces: 2 },
      )
    }

    await patchAgentGuidance(backlogPlatform, repoPlatform)
    await patchOpsReview({ backlogPlatform, repoPlatform })
    await patchOpsBacklog({ backlogPlatform, repoPlatform })
    await patchOpencodeJson()
    await patchOpencodePackage()
    if (!ctx.updateMode) await patchAgentsMd(ctx)

    if (!ctx.skipSkills) {
      await installSkills(backlogPlatform, repoPlatform, {
        forceOverwrite: ctx.forceOverwrite,
        updateMode: ctx.updateMode,
      })
    }
    // These patch SKILL.md files (pc-plan-archive, pc-ops-ship),
    // so they must run after installSkills has copied the skills into the project.
    await patchArchiveCommand({ backlogPlatform, repoPlatform })
    await patchOpsShip({ backlogPlatform, repoPlatform })
    await removeRetiredFiles()
    await generateFullstackEngineer({ updateMode: ctx.updateMode })
    await removeLegacyStartupDirectives()
    await recordManagedContent(CONTENT_DIR, dest, { updateMode: ctx.updateMode })
    success("Files copied to project root")
  } catch (err) {
    error(`Failed to copy content: ${err.message}`)
    exit(1)
  }
}

import { execa } from 'execa'
import fse from 'fs-extra'
import path from 'path'
import { createRequire } from 'node:module'
import { header, success, warn } from '../../utils/exec.js'
import { configPath } from '../../utils/paths.js'

const require = createRequire(import.meta.url)
const { version: harnessVersion } = require('../../../package.json')

function clampConcurrency(n) {
  const v = Number(n)
  if (!Number.isFinite(v)) return 3
  return Math.min(5, Math.max(1, Math.round(v)))
}

async function detectOpencodeVersion() {
  try {
    const result = await execa('opencode', ['--version'], { reject: false })
    if (result.exitCode !== 0) return null
    // `opencode --version` prints "opencode v2.0.22" on some builds and "2.0.22" on others;
    // record the bare version so the field does not churn between machines.
    const output = (result.stdout || result.stderr || '').trim()
    return output.match(/\d+\.\d+\.\d+[\w.-]*/)?.[0] ?? (output || null)
  } catch {
    return null
  }
}

export async function writeHarnessConfig(data) {
  header('Step 10, Writing onboarding metadata')

  const opencodeVersion = await detectOpencodeVersion()
  const cwd = data.cwd ?? process.cwd()
  const target = configPath(cwd)

  // Read the existing file so load-bearing config (models, maxConcurrent)
  // is preserved across metadata refreshes when not explicitly provided.
  const existing = await fse.readJson(target).catch(() => null)

  const selectedModels = Object.fromEntries(
    Object.entries({
      plan: data.planModel,
      build: data.buildModel,
      fast: data.fastModel,
    }).filter(([, value]) => value)
  )
  const models = Object.keys(selectedModels).length > 0
    ? { ...existing?.models, ...selectedModels }
    : existing?.models ?? null
  const maxConcurrent = clampConcurrency(data.maxConcurrentAgents ?? existing?.agents?.maxConcurrent ?? 3)

  const optionalTools = data.optionalTools ?? existing?.tools ?? {}
  const { caveman: _caveman, ...existingTools } = existing?.tools ?? {}
  const tools = {
    rtk: !!(optionalTools.rtk?.optedIn ?? optionalTools.rtk),
    quota: !!(optionalTools.quota?.optedIn ?? optionalTools.quota),
    simpleEnglish: !!(
      optionalTools.simpleEnglish?.optedIn ?? optionalTools.simpleEnglish ??
      optionalTools.caveman?.optedIn ?? optionalTools.caveman
    ),
    codegraph: !!(optionalTools.codegraph?.optedIn ?? optionalTools.codegraph),
    memory: !!(optionalTools.memory?.optedIn ?? optionalTools.memory),
    // humanizer was missing here, so a selection never survived a metadata
    // write and patchGuardrails always saw it as off, leaving its marker
    // section empty however the project was actually set up.
    humanizer: !!(optionalTools.humanizer?.optedIn ?? optionalTools.humanizer),
  }

  const payload = {
    ...existing,
    // Never lower a schema version a repository already records.
    version: Math.max(2, Number(existing?.version) || 0),
    generatedAt: new Date().toISOString(),
    harnessVersion,
    opencodeVersion,

    platform: {
      ...existing?.platform,
      backlog: data.backlogPlatform ?? 'none',
      repo: data.repoPlatform ?? 'none',
    },

    ...(models ? { models } : {}),

    agents: {
      ...existing?.agents,
      maxConcurrent,
    },

    source: {
      ...existing?.source,
      mode: data.sourceMode ?? 'current',
      roots: data.sourceRoots ?? [],
    },

    tools: { ...existingTools, ...tools },

    preexisting: {
      ...existing?.preexisting,
      design: !!data.hasDesign,
      architecture: !!data.hasArchitecture,
      openspec: !!data.hasOpenspec,
    },
  }

  try {
    await fse.ensureDir(path.dirname(target))
    await fse.writeJson(target, payload, { spaces: 2 })
    success('Wrote .opencode/harness.json')
    if (!opencodeVersion) warn('Could not detect opencode version, saved as null')
  } catch (err) {
    warn(`Could not write onboarding metadata: ${err.message}`)
  }
}

import { header, info, prompt, success, warn } from '../../utils/exec.js'
import { fetchModels } from '../../utils/models-cache.js'
import { buildDisplayModels, filterModelsByProvider, modelsPreset, pickModel, pickProvider } from './format.js'
import { writeModelsToConfigs } from './write.js'

async function pickRoleModel(role, allModels) {
  const rolePreset = modelsPreset.roles[role]
  const [first, ...rest] = rolePreset.info
  prompt(first)
  for (const line of rest) info(line)
  console.log()

  while (true) {
    const provider = await pickProvider('Provider:')
    const filtered = filterModelsByProvider(allModels, provider)
    const available = filtered.length > 0 ? filtered : allModels

    const suggestion = rolePreset.suggestions?.[provider]
    if (suggestion) info(`  Suggested: ${suggestion}`)
    if (filtered.length === 0 && provider) warn(`  No ${provider} models found: showing all`)

    const model = await pickModel(rolePreset.prompt, available)
    if (model !== '__back__') return model
  }
}

export async function chooseModels() {
  header('Step 7, Choose models');

  info('Fetching available models from models.dev...');
  const { models: rawModels, source } = await fetchModels();

  if (!rawModels) {
    warn('Could not fetch models (offline and no cache). Skipping model selection.');
    warn('Set models later in opencode.jsonc');
    return;
  }

  if (source === 'stale-cache') {
    warn('Network unavailable, using cached model list (may be outdated).');
  } else if (source === 'cache') {
    info('Using cached model list (refreshes weekly).');
  }

  const models = buildDisplayModels(rawModels);
  success(`${models.length} models available`);
  console.log();
  info('Three models: main session, engineers, and light commands.');
  info('Cost indicators: [$] cheap  [$$] mid  [$$$] expensive');
  info('Pick provider first, then search by name. Change later in opencode.jsonc');
  console.log();

  const planModel  = await pickRoleModel('plan',  models); console.log();
  const buildModel = await pickRoleModel('build', models); console.log();
  const fastModel  = await pickRoleModel('fast',  models); console.log();

  await writeModelsToConfigs({ planModel, buildModel, fastModel });

  console.log();
  warn('Make sure you have API access to the selected models.');
  warn('Change them anytime in opencode.jsonc');

  return { planModel, buildModel, fastModel };
}

import { execa } from "execa"
import fse from "fs-extra"
import path from "node:path"
import { commandExists, error, header, info, loading, success, warn } from "../../utils/exec.js"


async function cleanOpenspecFiles() {
  const cwd = process.cwd()
  const commandsDir = path.join(cwd, '.opencode', 'commands')
  const opencodeSkillsDir = path.join(cwd, '.opencode', 'skills')
  const agentsSkillsDir = path.join(cwd, '.agents', 'skills')

  // Delete opsx-* command files generated by OpenSpec: we use /plan-propose and /plan-apply instead
  if (await fse.pathExists(commandsDir)) {
    for (const f of await fse.readdir(commandsDir)) {
      if (f.startsWith('opsx-') && f.endsWith('.md')) {
        await fse.remove(path.join(commandsDir, f))
        info(`Removed generated command: ${f}`)
      }
    }
  }

  // Move .opencode/skills/* to .agents/skills/: skills should be in the universal location
  if (await fse.pathExists(opencodeSkillsDir)) {
    await fse.ensureDir(agentsSkillsDir)
    for (const dir of await fse.readdir(opencodeSkillsDir)) {
      const src = path.join(opencodeSkillsDir, dir)
      const dest = path.join(agentsSkillsDir, dir)
      if (!(await fse.pathExists(dest))) {
        await fse.move(src, dest)
        info(`Moved skill: ${dir} → .agents/skills/`)
      } else {
        await fse.remove(src)
      }
    }
    // Remove .opencode/skills if now empty
    const remaining = await fse.readdir(opencodeSkillsDir)
    if (remaining.length === 0) await fse.remove(opencodeSkillsDir)
  }

  success('OpenSpec generated files cleaned up')
}

export const openspecSteps = {
  check,
  install,
  init,
}

export async function initOpenspec() {
  header("Step 6, Initializing OpenSpec")

  let openSpec = await openspecSteps.check()
  if (!openSpec.available) {
    await openspecSteps.install()
  }

  openSpec = await openspecSteps.check()
  if (!openSpec.available) {
    warn("OpenSpec has not been installed. It is required to create changes.")
    return { ...openSpec, initialized: false }
  }

  const initResult = await openspecSteps.init()
  if (!initResult.initialized) {
    warn(
      "OpenSpec has not been initialized. It is required to create changes.",
    )
    return { ...openSpec, initialized: false }
  }

  await cleanOpenspecFiles()
  return { ...openSpec, initialized: true }
}

async function install() {
  info("Installing OpenSpec...")
  try {
    const result = await execa(
      "npm",
      ["install", "@fission-ai/openspec", "--global"],
      {
        cwd: process.cwd(),
        stdio: "pipe",
        reject: false,
      },
    )
    if (result.exitCode !== 0) {
      warn("OpenSpec install failed, check output above")
    }
    success("OpenSpec installed")
  } catch (err) {
    error(`Failed to run openspec install: ${err.message}`)
  }
}

async function check() {
  loading("Checking OpenSpec...")

  const available = await commandExists("openspec")

  if (available) success("OpenSpec is available")
  else warn("OpenSpec not found on PATH.")

  return { available }
}

async function init() {
  loading("Initializing OpenSpec...")
  try {
    const result = await execa(
      "npx",
      ["@fission-ai/openspec", "init", "--tools", "opencode", "--force"],
      {
        cwd: process.cwd(),
        reject: false,
      },
    )

    if (result.exitCode !== 0) {
      const stderr = (result.stderr || "").trim()
      const msg = stderr
        ? `init failed: ${stderr}`
        : `init failed with exit code ${result.exitCode}`
      throw new Error(msg)
    }
  } catch (err) {
    error(`Failed to run openspec init: ${err.message}`)
    return { initialized: false }
  }

  success("OpenSpec initialized")
  return { initialized: true }
}

